from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.ta_matchers.matchers import Any, Contains
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.msg_capture.expectation_builders.detailed import UniqueMessageDetail
from taf.ul.ettf.msg_capture.expectation_builders import WithStoredArgument
from taf.ul.ettf.msg_capture.storage import AppendToList


def bearer(erab_id):
    return Any({
        'ProtocolIE-Single-Container': Any({
            'value': Any({
                'E-RABs-ToBeAdded-SgNBAddReq-Item': Any({
                    'e-RAB-ID': erab_id
                })
            })
        })
    })


def bearers(bearers_container, bearers_aggregator=Contains):
    return Any({
        'ProtocolIE-Field': Any({
            'value': Any({
                'E-RABs-ToBeAdded-SgNBAddReqList': bearers_aggregator(*bearers_container)
            })
        })
    })


class sgnb(ExpectationsManager):
    @typed(erab_id=int)
    def with_sgnb_bearer(self, erab_id):
        self.store('SGNB_Bearers', bearer(erab_id), AppendToList)
        self.append_expectation(UniqueMessageDetail('protocolIEs', WithStoredArgument(bearers, 'SGNB_Bearers'), Contains))
